local M = {}

M.results = {}

function M.add(result)
	table.insert(M.results, result)
end

function M.last()
	return M.results[#M.results]
end

function M.remove_last()
	table.remove(M.results)
end

function M.remove(id)
	local remaining = {}

	for _, result in ipairs(M.results) do
		if result.extmark ~= id then
			table.insert(remaining, result)
		end
	end

	M.results = remaining
end

function M.get_buffer(bufnr)
	local results = {}

	for _, result in ipairs(M.results) do
		if result.bufnr == bufnr then
			table.insert(results, result)
		end
	end

	return results
end

function M.remove_buffer(bufnr)
	local remaining = {}

	for _, result in ipairs(M.results) do
		if result.bufnr ~= bufnr then
			table.insert(remaining, result)
		end
	end

	M.results = remaining
end

function M.clear()
	M.results = {}
end

return M

local M = {}

M.defaults = {
	enabled = true,

	virtual_text = true,

	adapter = "auto",

	runner = {
		timeout = 1000,
	},
}

M.options = {}

function M.setup(opts)
	M.options = vim.tbl_deep_extend("force", M.defaults, opts or {})
end

return M

local M = {}

local namespace = vim.api.nvim_create_namespace("OmniVision")

function M.show(bufnr, line, text, highlight)
	local lines = vim.split(text, "\n")

	local virt_lines = {}

	for _, item in ipairs(lines) do
		table.insert(virt_lines, {
			{
				item,
				highlight or "Comment",
			},
		})
	end

	return vim.api.nvim_buf_set_extmark(bufnr, namespace, line, 0, {
		virt_lines = virt_lines,
	})
end

function M.remove(bufnr, id)
	vim.api.nvim_buf_del_extmark(bufnr, namespace, id)
end

function M.clear_all()
	for _, buf in ipairs(vim.api.nvim_list_bufs()) do
		M.clear_buffer(buf)
	end
end

function M.clear_buffer(bufnr)
	vim.api.nvim_buf_clear_namespace(bufnr, namespace, 0, -1)
end

return M

